  </div>
  <div class="grp">
    <h2>生物群区 24</h2>
    <select id="sel-biome"></select>
    <button id="b-prev">← 上一舱</button>
    <button id="b-next">下一舱 →</button>
  </div>
  <div class="grp">
    <h2>参数</h2>
    <label class="chk">自转倍速 <span id="v-spin" style="margin-left:auto;color:var(--fg)"></span></label>
    <input id="r-spin" type="range" min="0" max="120" step="1" value="10">
    <label class="chk">昼夜周期（秒/日） <span id="v-day" style="margin-left:auto;color:var(--fg)"></span></label>
    <input id="r-day" type="range" min="20" max="300" step="5" value="90">
