<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { CSS2DRenderer, CSS2DObject } from 'three/addons/renderers/CSS2DRenderer.js';

/* ============================================================
   0. 常量：1 单位 = 100 m
   ============================================================ */
const U = 100;                       // 米/单位
const C = {
  ringR: 20,                         // 环半径 2 km
  tube: 2,                           // 舱体半径 200 m
  nBiome: 12,                        // 每环 12 舱
  ringGap: 26,                       // 两环间距 2.6 km
  spineR: 2.2,
  spineLen: 96,                      // 9.6 km
  spinPeriod: 90,                    // 真实自转周期(秒) → floor ≈ 1g
  launchYear: 2545, voyage: 170
};
const ARC = Math.PI * 2 / C.nBiome;  // 单舱弧度

// 24 个生物群区（顺序 = Ring A 1-12, Ring B 1-12）
const BIOMES = [
  ['Nova Scotia','boreal'], ['Labrador','tundra'],  ['Olympia','temperate'],
  ['Siberia','tundra'],     ['Steppes','grass'],    ['Mongolia','grass'],
  ['Prairie','farm'],       ['Yangtze','farm'],     ['Bengal','tropical'],
  ['Costa Rica','tropical'],['Amazonia','tropical'],['Sonora','arid'],
  ['Patagonia','temperate'],['Tasmania','temperate'],['Pampas','grass'],
  ['Iran','arid'],          ['Kiev','farm'],        ['Balkans','temperate'],
  ['Chukchi','tundra'],     ['Tibet','arid'],       ['Long Pond','aquatic'],
  ['Plata','aquatic'],      ['Ravnsborg','farm'],   ['Fu Jian','tropical']
];
const PROFILE = {
  tropical : {sky:0x9fc9d8, ground:0x2f5d2a, tree:0x1f4d1c, trunk:0x4a3b2a, trees:260, rocks:20, water:.35, crop:0,   sun:0xfff3d8, name:'热带雨林'},
  temperate: {sky:0xa8c4d8, ground:0x496b3a, tree:0x2f5c30, trunk:0x574433, trees:170, rocks:34, water:.28, crop:0,   sun:0xfff0dc, name:'温带林地'},
  boreal   : {sky:0x9fb6cc, ground:0x3f5c40, tree:0x27452f, trunk:0x4c3d2e, trees:200, rocks:40, water:.30, crop:0,   sun:0xffeedd, name:'北方针叶林'},
  tundra   : {sky:0xb7c8d6, ground:0x7d8a80, tree:0x4b5c46, trunk:0x5a5148, trees:40,  rocks:90, water:.20, crop:0,   sun:0xf2f6ff, name:'苔原 / 冻土'},
  arid     : {sky:0xd8c7a8, ground:0x9a7a4e, tree:0x5c6b3a, trunk:0x6b563a, trees:45,  rocks:120,water:.08, crop:0,   sun:0xfff0c8, name:'干旱荒漠'},
  grass    : {sky:0xaecadc, ground:0x6e8244, tree:0x3d5c33, trunk:0x5a4733, trees:55,  rocks:26, water:.22, crop:0,   sun:0xfff4e0, name:'草原'},
  farm     : {sky:0xaecadc, ground:0x5f7a3c, tree:0x35592f, trunk:0x54432f, trees:35,  rocks:12, water:.18, crop:1,   sun:0xfff6e6, name:'农业区'},
  aquatic  : {sky:0x9db9cf, ground:0x4a6b46, tree:0x2c5030, trunk:0x4e3f2d, trees:90,  rocks:22, water:.62, crop:0,   sun:0xf6fbff, name:'湖泊 / 湿地'}
};
const HOTSPOTS = {
  sunline : ['Sunline · 日线', '沿舱顶轴线铺设的灯带，是舱内唯一"太阳"。它按船内标准日循环调光，负责昼夜、季节与光合作用；日线故障是船上最受关注的检修项目之一。'],
  lake    : ['Lake · 淡水湖', '舱内水循环的缓冲池。水既是饮用与灌溉来源，也是宇宙射线的附加屏蔽和热惯量储备；水面沿环的曲率轻微倾斜。'],
  town    : ['Town · 聚居区', '每个生物群区都有小型聚居点，人口从几十到一百余人。全船约 2000 人，靠严格的物质与营养收支平衡维持七代人的航程。'],
  lock    : ['Bulkhead Lock · 舱段气闸', '两个生物群区之间的隔断门。它保证生态、气压与病害隔离；沿环走满 12 道气闸，就绕回原点。'],
  spoke   : ['Spoke Elevator · 辐条电梯', '从环底通往中央脊柱的电梯。上行时离心重力随半径线性减小，抵达脊柱时接近失重。'],
  wall    : ['Curvature · 环的曲率', '"地面"是环的最外壁。向前望去，地平线不是下沉而是上翘——这是半径 2 km 的环形栖息地最直观的特征。'],
  printer : ['Fabrication Bay · 打印车间', '脊柱零重力段的制造区。飞船不能补货，一切备件都要在此由回收原料重新打印出来。'],
  lab     : ['Bio Lab · 生化实验室', '监测 24 个生物群区的土壤、菌群与营养流的中枢；船载量子计算机在这里汇总全船生态账目。'],
  hangar  : ['Ferry Hangar · 渡船机库', '停放着往返飞船与行星/卫星的小型渡船，抵达目标恒星系后由它们执行登陆。'],
  spineax : ['Zero-g Axis · 失重轴心', '脊柱中轴几乎没有离心重力，移动靠扶手与推蹬；这里也是全船辐射屏蔽最厚的区域之一。']
};

/* ============================================================
   1. 渲染器 / 场景 / 相机
   ============================================================ */
const app = document.getElementById('webgl');
const renderer = new THREE.WebGLRenderer({antialias:true, powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;
renderer.outputColorSpace = THREE.SRGBColorSpace;
app.appendChild(renderer.domElement);

const labelRenderer = new CSS2DRenderer({element: document.getElementById('labels')});
labelRenderer.setSize(innerWidth, innerHeight);

const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(52, innerWidth/innerHeight, 0.05, 20000);
camera.position.set(46, 26, 70);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true; controls.dampingFactor = .06;
controls.minDistance = 8; controls.maxDistance = 620;
controls.autoRotate = true; controls.autoRotateSpeed = .35;

/* --- 程序化贴图：船体面板 --- */
function hullTexture(base = '#8d97a4', line = '#5c6673', n = 26){
  const s = 512, cv = document.createElement('canvas'); cv.width = cv.height = s;
  const g = cv.getContext('2d');
  g.fillStyle = base; g.fillRect(0,0,s,s);
  for (let i=0;i<1400;i++){                       // 微噪声
    g.fillStyle = `rgba(255,255,255,${Math.random()*.05})`;
    g.fillRect(Math.random()*s, Math.random()*s, 2, 2);
  }
  g.strokeStyle = line; g.lineWidth = 1.4;
  for (let i=1;i<n;i++){                          // 面板缝
    const p = i*s/n;
    g.beginPath(); g.moveTo(p,0); g.lineTo(p,s); g.stroke();
    g.beginPath(); g.moveTo(0,p); g.lineTo(s,p); g.stroke();
  }
  for (let i=0;i<70;i++){                         // 检修口
    const x=Math.random()*s, y=Math.random()*s, w=8+Math.random()*26, h=6+Math.random()*18;
    g.fillStyle = `rgba(0,0,0,${.10+Math.random()*.18})`; g.fillRect(x,y,w,h);
  }
  const t = new THREE.CanvasTexture(cv);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}
const TEX_HULL = hullTexture();
const TEX_RING = hullTexture('#9aa3ad', '#66707c', 40);
TEX_RING.repeat.set(24, 3); TEX_HULL.repeat.set(8, 6);

/* --- 星空 / 星云 / 尘埃 --- */
function buildStarfield(){
  const N = 26000, pos = new Float32Array(N*3), col = new Float32Array(N*3), sz = new Float32Array(N);
  const c = new THREE.Color();
  for (let i=0;i<N;i++){
    const r = 6000 + Math.random()*7000;
    const t = Math.acos(2*Math.random()-1), p = Math.random()*Math.PI*2;
    pos[i*3]   = r*Math.sin(t)*Math.cos(p);
    pos[i*3+1] = r*Math.cos(t);
    pos[i*3+2] = r*Math.sin(t)*Math.sin(p);
    const h = Math.random();
    c.setHSL(h<.6 ? .58+Math.random()*.08 : .06+Math.random()*.09, .5*Math.random(), .55+Math.random()*.45);
    col[i*3]=c.r; col[i*3+1]=c.g; col[i*3+2]=c.b;
    sz[i] = Math.random()<.03 ? 26+Math.random()*40 : 6+Math.random()*14;
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(pos,3));
  geo.setAttribute('color', new THREE.BufferAttribute(col,3));
  geo.setAttribute('asize', new THREE.BufferAttribute(sz,1));
  const mat = new THREE.ShaderMaterial({
    transparent:true, depthWrite:false, blending:THREE.AdditiveBlending,
    uniforms:{uT:{value:0}},
    vertexShader:`attribute float asize; attribute vec3 color; varying vec3 vC; varying float vT;
      uniform float uT;
      void main(){ vC=color; vT=fract(sin(dot(position.xy,vec2(12.9,78.2)))*43758.5);
        vec4 mv=modelViewMatrix*vec4(position,1.); gl_Position=projectionMatrix*mv;
        gl_PointSize=asize*(300./-mv.z)*(0.82+0.18*sin(uT*1.7+vT*31.4)); }`,
    fragmentShader:`varying vec3 vC; void main(){
        float d=length(gl_PointCoord-.5); if(d>.5) discard;
        float a=smoothstep(.5,.02,d); gl_FragColor=vec4(vC,a); }`
  });
  return new THREE.Points(geo, mat);
}
const stars = buildStarfield(); scene.add(stars);

function nebulaSprite(color, size, x, y, z){
  const s=256, cv=document.createElement('canvas'); cv.width=cv.height=s;
  const g=cv.getContext('2d'), grd=g.createRadialGradient(s/2,s/2,0,s/2,s/2,s/2);
  grd.addColorStop(0,'rgba(255,255,255,.30)'); grd.addColorStop(.35,color);
  grd.addColorStop(1,'rgba(0,0,0,0)');
  g.fillStyle=grd; g.fillRect(0,0,s,s);
  const t=new THREE.CanvasTexture(cv); t.colorSpace=THREE.SRGBColorSpace;
  const sp=new THREE.Sprite(new THREE.SpriteMaterial({map:t,transparent:true,depthWrite:false,
    blending:THREE.AdditiveBlending,opacity:.55}));
  sp.scale.setScalar(size); sp.position.set(x,y,z); return sp;
}
scene.add(nebulaSprite('rgba(60,110,220,.38)', 7000, -5200, 1800, -6000));
scene.add(nebulaSprite('rgba(190,70,180,.26)', 5200,  4800,-2200, -6400));
scene.add(nebulaSprite('rgba(40,190,190,.20)', 4200, -1200,-3000,  6600));

// 目标恒星 Tau Ceti（船首方向 -Z）
const targetStar = nebulaSprite('rgba(255,230,170,.85)', 620, 0, 0, -9000);
targetStar.material.opacity = .95; scene.add(targetStar);

// 掠过的星际尘埃（体现 0.1c 航行）
const DUST = 1400;
const dustGeo = new THREE.BufferGeometry();
const dustPos = new Float32Array(DUST*3);
const resetDust = i => {
  dustPos[i*3]   = (Math.random()-.5)*340;
  dustPos[i*3+1] = (Math.random()-.5)*220;
  dustPos[i*3+2] = -260 - Math.random()*420;
};
for (let i=0;i<DUST;i++) resetDust(i);
dustGeo.setAttribute('position', new THREE.BufferAttribute(dustPos,3));
const dust = new THREE.Points(dustGeo, new THREE.PointsMaterial({
  color:0x9fd4ff, size:.55, transparent:true, opacity:.55, depthWrite:false,
  blending:THREE.AdditiveBlending}));
scene.add(dust);

