/* --- 中央脊柱 --- */
function buildSpine(){
  const g = new THREE.Group();
  const body = new THREE.Mesh(new THREE.CylinderGeometry(C.spineR, C.spineR, C.spineLen, 40, 1, true), M.hull);
  body.rotation.x = Math.PI/2; g.add(body);
  // 加强环
  for (let z=-C.spineLen/2+4; z<=C.spineLen/2-4; z+=6){
    const rib = new THREE.Mesh(new THREE.TorusGeometry(C.spineR*1.06, .12, 8, 40), M.dark);
    rib.position.z = z; g.add(rib);
  }
  // 舱段外挂模块 + 舷灯
  const mod = new THREE.BoxGeometry(1.5,1.1,4.2);
  for (let i=0;i<14;i++){
    const a = i*1.12, z = -C.spineLen/2+9 + i*5.6;
    const m = new THREE.Mesh(mod, M.dark);
    m.position.set(Math.cos(a)*(C.spineR+.6), Math.sin(a)*(C.spineR+.6), z);
    m.lookAt(0,0,z); g.add(m);
    const l = new THREE.Mesh(new THREE.BoxGeometry(.9,.12,3.4), M.glass);
    l.position.copy(m.position).multiplyScalar(1.06); l.position.z = z; l.lookAt(0,0,z);
    g.add(l);
  }
  // 机库（脊柱中段）+ 两艘渡船
  const hangar = new THREE.Mesh(new THREE.CylinderGeometry(C.spineR*1.7, C.spineR*1.7, 7, 24), M.hull);
  hangar.rotation.x = Math.PI/2; g.add(hangar); parts.hangar = hangar;
  const doors = new THREE.Mesh(new THREE.CylinderGeometry(C.spineR*1.72, C.spineR*1.72, 2.2, 24, 1, true), M.glass);
  doors.rotation.x = Math.PI/2; doors.material = M.glass; g.add(doors);
  for (const s of [-1,1]){
    const f = new THREE.Group();
    const hullF = new THREE.Mesh(new THREE.CapsuleGeometry(.55, 2.4, 6, 12), M.tank);
    hullF.rotation.z = Math.PI/2; f.add(hullF);
    const wing = new THREE.Mesh(new THREE.BoxGeometry(2.2,.08,1.5), M.dark); f.add(wing);
    const noz  = new THREE.Mesh(new THREE.ConeGeometry(.35,.7,10), M.dark);
    noz.rotation.z = Math.PI/2; noz.position.x = -1.9; f.add(noz);
    f.position.set(0, s*(C.spineR*1.7+1.1), 1.4); f.rotation.x = s>0?0:Math.PI;
    g.add(f);
  }
  return g;
}
parts.spine = buildSpine(); ship.add(parts.spine);

/* --- 船首防护屏（whipple shield / dust lens） --- */
function buildShield(){
  const g = new THREE.Group();
  g.position.z = -C.spineLen/2 - 3;
  const cone = new THREE.Mesh(new THREE.ConeGeometry(9, 7.5, 64, 1, true), M.shield);
  cone.rotation.x = -Math.PI/2; cone.position.z = -3.4; g.add(cone);
  for (let i=0;i<3;i++){                                  // 多层薄板
    const p = new THREE.Mesh(new THREE.RingGeometry(2.4, 8.4-i*.7, 64), M.shield);
    p.position.z = -.9 - i*1.5; p.material = M.shield; g.add(p);
  }
  const neck = new THREE.Mesh(new THREE.CylinderGeometry(2.4, C.spineR, 4, 32), M.hull);
  neck.rotation.x = Math.PI/2; neck.position.z = 1.4; g.add(neck);
  // 前向传感 / 激光测距
  const mast = new THREE.Mesh(new THREE.CylinderGeometry(.1,.1,5,8), M.dark);
  mast.rotation.x = Math.PI/2; mast.position.z = -8; g.add(mast);
  const tip = new THREE.Mesh(new THREE.SphereGeometry(.32, 16, 12), M.glass);
  tip.position.z = -10.4; g.add(tip);
  return g;
}
