/* --- 船尾：燃料舱 + 减速推进 + 散热板 --- */
function buildDrive(){
  const g = new THREE.Group();
  const z0 = C.spineLen/2;
  g.position.z = z0;
  const trunk = new THREE.Mesh(new THREE.CylinderGeometry(C.spineR, 3.2, 10, 32), M.hull);
  trunk.rotation.x = Math.PI/2; trunk.position.z = 4.5; g.add(trunk);
  // 4 个燃料球罐（氘/氦-3）
  for (let i=0;i<4;i++){
    const a = i*Math.PI/2 + Math.PI/4;
    const t = new THREE.Mesh(new THREE.SphereGeometry(2.6, 28, 20), M.tank);
    t.position.set(Math.cos(a)*4.6, Math.sin(a)*4.6, 11); g.add(t);
    const pipe = new THREE.Mesh(new THREE.CylinderGeometry(.16,.16,5,8), M.dark);
    pipe.position.copy(t.position).multiplyScalar(.5); pipe.position.z = 11;
    pipe.rotation.z = Math.PI/2; pipe.rotation.y = -a; g.add(pipe);
  }
  parts.tanks = g;
  // 反应室 + 磁喷管
  const chamber = new THREE.Mesh(new THREE.SphereGeometry(2.9, 32, 22), M.gold);
  chamber.position.z = 17; g.add(chamber);
  const noz = new THREE.Mesh(new THREE.CylinderGeometry(1.6, 4.6, 7, 40, 1, true), M.dark);
  noz.rotation.x = -Math.PI/2; noz.position.z = 22.5; noz.material.side = THREE.DoubleSide; g.add(noz);
  for (let i=0;i<4;i++){                                  // 磁约束线圈
    const coil = new THREE.Mesh(new THREE.TorusGeometry(2.0+i*.7, .22, 8, 32), M.gold);
    coil.position.z = 19.6+i*1.7; g.add(coil);
  }
  // 排焰
  const plumeMat = new THREE.ShaderMaterial({
    transparent:true, depthWrite:false, blending:THREE.AdditiveBlending, side:THREE.DoubleSide,
    uniforms:{uT:{value:0}},
    vertexShader:`varying vec2 vUv; void main(){vUv=uv; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}`,
    fragmentShader:`varying vec2 vUv; uniform float uT;
      void main(){ float t=vUv.y;
        float n=sin(vUv.x*38.+uT*15.)*.5+.5;
        float a=(1.-t)*(.55+.45*n)*smoothstep(0.,.12,t);
        vec3 c=mix(vec3(.55,.85,1.), vec3(.12,.30,.95), t);
        gl_FragColor=vec4(c, a*.85); }`
  });
  const plume = new THREE.Mesh(new THREE.ConeGeometry(4.4, 46, 40, 20, true), plumeMat);
  plume.rotation.x = -Math.PI/2; plume.position.z = 26+23; g.add(plume);
  parts.plume = plume; parts.plumeMat = plumeMat;
  const glow = new THREE.PointLight(0x88bbff, 900, 120); glow.position.z = 27; g.add(glow);
  parts.driveGlow = glow;
  // 散热板
  parts.rads = [];
  for (const s of [-1,1]){
    const r = new THREE.Mesh(new THREE.BoxGeometry(.14, 12, 22), M.rad);
    r.position.set(s*6.2, 0, 6); r.rotation.z = s*.12; g.add(r); parts.rads.push(r);
  }
  return g;
}
parts.drive = buildDrive(); ship.add(parts.drive);

/* --- 两个环 + 辐条 --- */
function buildRing(ringIdx){
  const g = new THREE.Group();
  g.position.z = (ringIdx === 0 ? -1 : 1) * C.ringGap/2;
  const winGeo = new THREE.BoxGeometry(.5, .12, .9);
  const winMats = {};
  for (let i=0;i<C.nBiome;i++){
    const gi = ringIdx*C.nBiome + i;
    const [name, prof] = BIOMES[gi];
    const p = PROFILE[prof];
    // 舱段外壳：带缝隙的圆环段
    const seg = new THREE.Mesh(
      new THREE.TorusGeometry(C.ringR, C.tube, 26, 64, ARC*0.955),
      M.ringHull.clone());
    seg.rotation.z = i*ARC + ARC*.0225;
    seg.userData = {kind:'biome', index:gi, name, prof};
    g.add(seg); biomeMeshes.push(seg);
    // 舱段间隔舱 / 气闸环
    const lock = new THREE.Mesh(new THREE.TorusGeometry(C.ringR, C.tube*1.06, 12, 20, ARC*.045), M.dark);
    lock.rotation.z = i*ARC; g.add(lock);
    // 舷窗灯带（两侧）——用实例化小方块
    const inst = new THREE.InstancedMesh(winGeo,
      new THREE.MeshStandardMaterial({color:p.sky, emissive:p.sky, emissiveIntensity:1.5}), 40);
    const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), sc = new THREE.Vector3(1,1,1);
    let k = 0;
    for (let j=0;j<20;j++){
      const th = i*ARC + ARC*(.06 + .88*j/19);
      for (const phi of [1.25, -1.25]){
        const rad = C.ringR + C.tube*1.005*Math.cos(phi);
        const pos = new THREE.Vector3(rad*Math.cos(th), rad*Math.sin(th), C.tube*1.005*Math.sin(phi));
        const n = new THREE.Vector3(Math.cos(phi)*Math.cos(th), Math.cos(phi)*Math.sin(th), Math.sin(phi));
        q.setFromUnitVectors(new THREE.Vector3(0,1,0), n);
        m4.compose(pos, q, sc); inst.setMatrixAt(k++, m4);
      }
    }
    inst.instanceMatrix.needsUpdate = true; g.add(inst);
    winMats[gi] = inst.material;
  }
  // 辐条 ×6 + 电梯井
  for (let i=0;i<6;i++){
    const a = i*Math.PI/3;
    const len = C.ringR - C.spineR;
    const sp = new THREE.Mesh(new THREE.CylinderGeometry(.42,.6,len,14), M.hull);
    sp.position.set(Math.cos(a)*(C.spineR+len/2), Math.sin(a)*(C.spineR+len/2), 0);
    sp.rotation.z = a - Math.PI/2; g.add(sp);
    const cab = new THREE.Mesh(new THREE.BoxGeometry(.9,.9,1.4), M.glass);
    cab.position.set(Math.cos(a)*(C.spineR+len*.62), Math.sin(a)*(C.spineR+len*.62), 0);
    g.add(cab);
  }
  // 环毂（与脊柱的旋转接口）
  const hub = new THREE.Mesh(new THREE.CylinderGeometry(C.spineR*1.35, C.spineR*1.35, 4.5, 32), M.dark);
  hub.rotation.x = Math.PI/2; g.add(hub);
  g.userData.winMats = winMats;
  return g;
}
parts.ringA = buildRing(0); parts.ringB = buildRing(1);
