/* ============================================================
   3. 内部：生物群区（步行）与脊柱（零重力）
   ============================================================ */
const interior = new THREE.Group(); interior.visible = false; scene.add(interior);
const intLights = [];
let curBiome = 0, dayT = .28;             // 0..1 舱内一日
const hotMeshes = [];

function disposeGroup(g){
  g.traverse(o=>{
    if (o.geometry) o.geometry.dispose();
    if (o.material){ (Array.isArray(o.material)?o.material:[o.material]).forEach(m=>m.dispose()); }
  });
  g.clear();
}

/* 环内坐标：theta 沿环，phi 绕舱截面（0 = 地面最外侧，±π/2 = 侧壁，π = 舱顶） */
function biomePos(theta, phi, h = 0){
  const rr = C.tube - h;
  const rad = C.ringR + rr*Math.cos(phi);
  return new THREE.Vector3(rad*Math.cos(theta), rad*Math.sin(theta), rr*Math.sin(phi));
}
function biomeUp(theta, phi){   // 离心重力方向的反向 = 指向舱轴
  return new THREE.Vector3(Math.cos(phi)*Math.cos(theta), Math.cos(phi)*Math.sin(theta), Math.sin(phi)).negate();
}
function biomeTangent(theta){ return new THREE.Vector3(-Math.sin(theta), Math.cos(theta), 0); }
function biomeLateral(theta, phi){
  return new THREE.Vector3(-Math.sin(phi)*Math.cos(theta), -Math.sin(phi)*Math.sin(theta), Math.cos(phi));
}
/* 贴合环内壁的曲面带（草地 / 水面 / 小路） */
function curvedStrip(t0, t1, p0, p1, h, mat, seg = [60, 10]){
  const g = new THREE.BufferGeometry(), pos = [], idx = [], uv = [], nor = [];
  const [su, sv] = seg;
  for (let i=0;i<=su;i++){
    const th = t0 + (t1-t0)*i/su;
    for (let j=0;j<=sv;j++){
      const ph = p0 + (p1-p0)*j/sv;
      const p = biomePos(th, ph, h), n = biomeUp(th, ph);
      pos.push(p.x,p.y,p.z); nor.push(n.x,n.y,n.z); uv.push(i/su*8, j/sv*2);
    }
  }
  for (let i=0;i<su;i++) for (let j=0;j<sv;j++){
    const a=i*(sv+1)+j, b=a+sv+1;
    idx.push(a,b,a+1, b,b+1,a+1);
  }
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos,3));
  g.setAttribute('normal',   new THREE.Float32BufferAttribute(nor,3));
  g.setAttribute('uv',       new THREE.Float32BufferAttribute(uv,2));
  g.setIndex(idx);
  return new THREE.Mesh(g, mat);
}
function hotspot(key, pos, group){
  const m = new THREE.Mesh(new THREE.SphereGeometry(.09, 14, 10),
    new THREE.MeshBasicMaterial({color:0x9fe8ff, transparent:true, opacity:.9}));
  m.position.copy(pos); m.userData = {kind:'hot', key}; group.add(m); hotMeshes.push(m);
  const halo = new THREE.Sprite(new THREE.SpriteMaterial({
    map: haloTex(), color:0x9fe8ff, transparent:true, opacity:.55, depthWrite:false,
    blending:THREE.AdditiveBlending}));
  halo.scale.setScalar(.75); m.add(halo);
  const d = document.createElement('div'); d.className='lbl'; d.textContent = HOTSPOTS[key][0].split(' · ')[1] || HOTSPOTS[key][0];
  d.onclick = e => { e.stopPropagation(); showCard(key); };
  m.add(new CSS2DObject(d));
  return m;
}
let _halo;
function haloTex(){
  if (_halo) return _halo;
  const s=64, cv=document.createElement('canvas'); cv.width=cv.height=s;
  const g=cv.getContext('2d'), r=g.createRadialGradient(s/2,s/2,0,s/2,s/2,s/2);
  r.addColorStop(0,'rgba(255,255,255,1)'); r.addColorStop(.4,'rgba(160,230,255,.5)');
  r.addColorStop(1,'rgba(0,0,0,0)');
  g.fillStyle=r; g.fillRect(0,0,s,s);
  _halo = new THREE.CanvasTexture(cv); return _halo;
}

/* --- 建造一个生物群区内部 --- */
function buildBiome(index){
  disposeGroup(interior); hotMeshes.length = 0; intLights.length = 0;
  const [name, profKey] = BIOMES[index];
  const P = PROFILE[profKey];
  const t0 = 0.012, t1 = ARC - 0.012;

  // 舱壳（内表面）：既是"天空"也是侧壁
  const shell = new THREE.Mesh(
    new THREE.TorusGeometry(C.ringR, C.tube, 40, 140, ARC),
    new THREE.MeshStandardMaterial({color:P.sky, roughness:1, metalness:0,
      emissive:P.sky, emissiveIntensity:.30, side:THREE.BackSide}));
  interior.add(shell); interior.userData.shell = shell;

  // 端隔壁 + 气闸门
  for (const th of [0, ARC]){
    const cap = new THREE.Mesh(new THREE.CircleGeometry(C.tube, 40),
      new THREE.MeshStandardMaterial({color:0x6f7a85, roughness:.8, metalness:.4, side:THREE.DoubleSide}));
    cap.position.set(C.ringR*Math.cos(th), C.ringR*Math.sin(th), 0);
    cap.lookAt(cap.position.clone().add(biomeTangent(th)));
    interior.add(cap);
    const door = new THREE.Mesh(new THREE.BoxGeometry(1.1, 1.5, .08),
      new THREE.MeshStandardMaterial({color:0x2f3a46, metalness:.7, roughness:.3,
        emissive:0x1a6a7a, emissiveIntensity:.5}));
    const dp = biomePos(th, 0, .75);
    door.position.copy(dp);
    door.lookAt(dp.clone().add(biomeTangent(th).multiplyScalar(th===0?-1:1)));
    door.up.copy(biomeUp(th,0)); interior.add(door);
    hotspot('lock', biomePos(th===0? t0+.006 : t1-.006, 0, 1.9), interior);
  }

  // 地面
  const ground = curvedStrip(t0, t1, -1.35, 1.35, 0.002,
    new THREE.MeshStandardMaterial({color:P.ground, roughness:.95, metalness:0}), [90, 18]);
  interior.add(ground);

  // 湖 / 河
  if (P.water > .05){
    const wc = t0 + (t1-t0)*.62, wHalf = (t1-t0)*.16*(P.water*1.6);
    const water = curvedStrip(wc-wHalf, wc+wHalf, -.55*P.water*1.8, .55*P.water*1.8, .012,
      new THREE.MeshStandardMaterial({color:0x21507a, roughness:.12, metalness:.35,
        transparent:true, opacity:.9}), [40, 14]);
    interior.add(water); interior.userData.water = water;
    hotspot('lake', biomePos(wc, 0, .55), interior);
  }
  // 小路（沿环轴向）
  interior.add(curvedStrip(t0, t1, -.10, .10, .016,
    new THREE.MeshStandardMaterial({color:0x8a7c63, roughness:.9}), [70, 3]));

  // 植被（实例化：树干 + 树冠）
  const rnd = mulberry32(index*7919 + 13);
  const nT = P.trees;
  const trunkG = new THREE.CylinderGeometry(.018,.026,.24,6); trunkG.translate(0,.12,0);
  const conif = profKey==='boreal' || profKey==='tundra' || profKey==='temperate';
  const canopyG = conif ? new THREE.ConeGeometry(.11,.42,7) : new THREE.SphereGeometry(.14,9,7);
  canopyG.translate(0, conif? .24+.21 : .24+.13, 0);
  const trunks = new THREE.InstancedMesh(trunkG, new THREE.MeshStandardMaterial({color:P.trunk, roughness:.95}), nT);
  const canopy = new THREE.InstancedMesh(canopyG, new THREE.MeshStandardMaterial({color:P.tree, roughness:.9}), nT);
  const m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), YP = new THREE.Vector3(0,1,0);
  for (let i=0;i<nT;i++){
    const th = t0 + (t1-t0)*rnd(), ph = (rnd()*2-1)*1.15;
    if (P.water>.05 && Math.abs(th - (t0+(t1-t0)*.62)) < (t1-t0)*.13 && Math.abs(ph)<.6){ // 避开水面
      i--; continue;
    }
    const p = biomePos(th, ph, 0), up = biomeUp(th, ph);
    q.setFromUnitVectors(YP, up);
    const s = .7 + rnd()*.9;
    m4.compose(p, q, new THREE.Vector3(s,s,s));
    trunks.setMatrixAt(i, m4); canopy.setMatrixAt(i, m4);
  }
  trunks.instanceMatrix.needsUpdate = canopy.instanceMatrix.needsUpdate = true;
  interior.add(trunks, canopy);

  // 岩石
  const rockG = new THREE.DodecahedronGeometry(.07, 0);
  const rocks = new THREE.InstancedMesh(rockG,
    new THREE.MeshStandardMaterial({color:0x8b8f93, roughness:.95}), P.rocks);
  for (let i=0;i<P.rocks;i++){
    const th=t0+(t1-t0)*rnd(), ph=(rnd()*2-1)*1.3, p=biomePos(th,ph,0);
    q.setFromUnitVectors(YP, biomeUp(th,ph)).multiply(
      new THREE.Quaternion().setFromEuler(new THREE.Euler(rnd()*3,rnd()*3,rnd()*3)));
    const s=.5+rnd()*1.8; m4.compose(p,q,new THREE.Vector3(s,s,s*1.3)); rocks.setMatrixAt(i,m4);
  }
  rocks.instanceMatrix.needsUpdate = true; interior.add(rocks);

  // 农田条垄
  if (P.crop){
    const cropG = new THREE.BoxGeometry(.02,.12,.9); cropG.translate(0,.06,0);
    const rows = 260;
    const crops = new THREE.InstancedMesh(cropG,
      new THREE.MeshStandardMaterial({color:0x93a83f, roughness:.9}), rows);
    for (let i=0;i<rows;i++){
      const th = t0+(t1-t0)*(.05+.35*(i/rows)), ph = -1.0 + 2.0*((i*37%100)/100);
      const p = biomePos(th, ph, 0);
      q.setFromUnitVectors(YP, biomeUp(th, ph));
      const tang = biomeTangent(th);
      const rot = new THREE.Quaternion().setFromAxisAngle(biomeUp(th,ph), Math.atan2(tang.y,tang.x));
      m4.compose(p, q.premultiply(rot), new THREE.Vector3(1,1,1));
      crops.setMatrixAt(i, m4);
    }
    crops.instanceMatrix.needsUpdate = true; interior.add(crops);
  }

  // 聚居区
  const townTh = t0 + (t1-t0)*.22;
  const bGeo = new THREE.BoxGeometry(.22,.16,.3); bGeo.translate(0,.08,0);
  const town = new THREE.InstancedMesh(bGeo,
    new THREE.MeshStandardMaterial({color:0xcfd6dd, roughness:.7,
      emissive:0xffd9a0, emissiveIntensity:.12}), 26);
  for (let i=0;i<26;i++){
    const th = townTh + (rnd()-.5)*(t1-t0)*.14, ph = (rnd()-.5)*1.1;
    const p = biomePos(th, ph, 0);
    q.setFromUnitVectors(YP, biomeUp(th, ph));
    q.premultiply(new THREE.Quaternion().setFromAxisAngle(biomeUp(th,ph), rnd()*6.28));
    const s=.8+rnd()*1.1; m4.compose(p,q,new THREE.Vector3(s,s,s)); town.setMatrixAt(i,m4);
  }
  town.instanceMatrix.needsUpdate = true; interior.add(town);
  hotspot('town', biomePos(townTh, 0, 1.0), interior);

  // Sunline：舱顶轴向灯带
  const sun = new THREE.Mesh(new THREE.TorusGeometry(C.ringR - C.tube + .12, .05, 8, 120, ARC),
    new THREE.MeshBasicMaterial({color:0xffffff}));
  interior.add(sun); interior.userData.sun = sun;
  const glowTube = new THREE.Mesh(new THREE.TorusGeometry(C.ringR - C.tube + .12, .16, 8, 120, ARC),
    new THREE.MeshBasicMaterial({color:0xfff3d0, transparent:true, opacity:.35,
      blending:THREE.AdditiveBlending, depthWrite:false}));
  interior.add(glowTube); interior.userData.sunGlow = glowTube;
  hotspot('sunline', biomePos(t0+(t1-t0)*.5, Math.PI - .18, 0), interior);
  hotspot('wall',    biomePos(t1-.02, 1.32, .2), interior);
  hotspot('spoke',   biomePos(t0+(t1-t0)*.5, .02, .4), interior);

  // 辐条底站（电梯口）
  const stat = new THREE.Mesh(new THREE.CylinderGeometry(.3,.36,.9,16),
    new THREE.MeshStandardMaterial({color:0x9aa3ad, metalness:.6, roughness:.4}));
  const sp = biomePos(t0+(t1-t0)*.5, 0, 0);
  stat.position.copy(sp);
  stat.quaternion.setFromUnitVectors(YP, biomeUp(t0+(t1-t0)*.5, 0));
  interior.add(stat);

  // 光源：沿 sunline 布点光
  for (let i=0;i<5;i++){
    const th = t0 + (t1-t0)*(i+.5)/5;
    const L = new THREE.PointLight(P.sun, 2.2, 14, 1.4);
    L.position.copy(biomePos(th, Math.PI - .1, 0));
    interior.add(L); intLights.push(L);
  }
  const amb = new THREE.AmbientLight(P.sky, .55); interior.add(amb); intLights.push(amb);

  interior.userData.profile = P;
  interior.userData.range = [t0, t1];
  curBiome = index;
  document.getElementById('sel-biome').value = String(index);
  document.getElementById('h-loc').textContent =
    `${name}（${P.name}） · Ring ${index < C.nBiome ? 'A' : 'B'} #${index % C.nBiome + 1}`;
}

/* --- 脊柱内部（零重力） --- */
function buildSpineInterior(){
  disposeGroup(interior); hotMeshes.length = 0; intLights.length = 0;
  const L = 40, R = C.spineR*.92;
  const wallMat = new THREE.MeshStandardMaterial({color:0x8e97a1, roughness:.6, metalness:.45,
    side:THREE.BackSide, map:hullTexture('#939ca6','#5f6a76',18)});
  wallMat.map.repeat.set(10,4);
  const tube = new THREE.Mesh(new THREE.CylinderGeometry(R, R, L, 40, 1, true), wallMat);
  tube.rotation.x = Math.PI/2; interior.add(tube);
  for (const s of [-1,1]){
    const cap = new THREE.Mesh(new THREE.CircleGeometry(R, 40),
      new THREE.MeshStandardMaterial({color:0x5d666f, roughness:.7, metalness:.5, side:THREE.DoubleSide}));
    cap.position.z = s*L/2; interior.add(cap);
  }
  // 加强环 + 扶手 + 灯带
  for (let z=-L/2+2; z<=L/2-2; z+=2.5){
    const rib = new THREE.Mesh(new THREE.TorusGeometry(R*.99, .05, 6, 32),
      new THREE.MeshStandardMaterial({color:0x39424c, metalness:.8, roughness:.35}));
    rib.position.z = z; interior.add(rib);
    const lamp = new THREE.Mesh(new THREE.BoxGeometry(.06,.5,.06),
      new THREE.MeshBasicMaterial({color:0xdff0ff}));
    lamp.position.set(0, R*.94, z); interior.add(lamp);
    if (Math.random()<.5){
      const L2 = new THREE.PointLight(0xcfe6ff, .9, 7, 1.5);
      L2.position.set(0, R*.8, z); interior.add(L2); intLights.push(L2);
    }
  }
  const rail = new THREE.Mesh(new THREE.CylinderGeometry(.04,.04,L-1,8),
    new THREE.MeshStandardMaterial({color:0xc8d2dc, metalness:.9, roughness:.25}));
  rail.rotation.x = Math.PI/2; rail.position.y = -R*.55; interior.add(rail);
  // 设备架 / 打印车间 / 实验室
  const rackMat = new THREE.MeshStandardMaterial({color:0x59636e, metalness:.6, roughness:.4,
    emissive:0x0d3a44, emissiveIntensity:.6});
  for (let i=0;i<16;i++){
    const z = -L/2+3 + i*2.4, a = (i%2? .9 : -.9) + (i*.37);
    const box = new THREE.Mesh(new THREE.BoxGeometry(.7,.5,1.6), rackMat);
    box.position.set(Math.cos(a)*(R-.42), Math.sin(a)*(R-.42), z);
    box.lookAt(0,0,z); interior.add(box);
    const panel = new THREE.Mesh(new THREE.PlaneGeometry(.4,.22),
      new THREE.MeshBasicMaterial({color: i%3? 0x66e0ff : 0xffc46b}));
    panel.position.copy(box.position).multiplyScalar(.93); panel.position.z=z;
    panel.lookAt(0,0,z); interior.add(panel);
  }
  hotspot('printer', new THREE.Vector3(0, -.5, -10), interior);
  hotspot('lab',     new THREE.Vector3(0,  .6,   4), interior);
  hotspot('hangar',  new THREE.Vector3(0, -.8,  14), interior);
  hotspot('spineax', new THREE.Vector3(0,  0,   -2), interior);
  interior.add(new THREE.AmbientLight(0x93a8c0, .7));
  document.getElementById('h-loc').textContent = '中央脊柱 · 零重力舱段';
}

/* ============================================================
   4. 模式切换 / 第一人称控制器
   ============================================================ */
let mode = 'ext';               // 'ext' | 'walk' | 'fly'
const FP = {theta:0, phi:0, yaw:0, pitch:0, pos:new THREE.Vector3(), keys:new Set(),
            drag:false, lx:0, ly:0};
let tween = null;

function setMode(m){
  mode = m;
  controls.enabled = (m === 'ext');
  ship.visible = stars.visible = dust.visible = (m === 'ext');
  scene.traverse(o=>{ if(o.isSprite && o.parent===scene) o.visible = (m==='ext'); });
  interior.visible = (m !== 'ext');
  labelObjs.forEach(o=>o.visible = (m==='ext') && showLabels);
  document.getElementById('help-ext').style.display = m==='ext' ? '' : 'none';
  document.getElementById('help-in').style.display  = m==='ext' ? 'none' : '';
  document.getElementById('h-mode').textContent =
    m==='ext' ? '外部 / 深空' : (m==='walk' ? '舱内步行（1 g）' : '脊柱 / 零重力');
  document.getElementById('h-k1').textContent = m==='ext' ? '当前舱区' : '所在位置';
  for (const [id,on] of [['b-ext',m==='ext'],['b-in',m==='walk'],['b-spine',m==='fly']])
    document.getElementById(id).classList.toggle('on', on);
  if (m === 'ext'){ document.getElementById('h-loc').textContent = '—'; hideCard(); }
  camera.near = m==='ext' ? .05 : .02;
  camera.far  = m==='ext' ? 20000 : 400;
  camera.updateProjectionMatrix();
}
function enterBiome(i){
  buildBiome(i);
  const [t0,t1] = interior.userData.range;
  FP.theta = t0 + (t1-t0)*.42; FP.phi = 0; FP.yaw = 0; FP.pitch = -.05;
  setMode('walk'); syncFPCamera();
}
function enterSpine(){
  buildSpineInterior();
  FP.pos.set(0, 0, 16); FP.yaw = Math.PI; FP.pitch = 0;
  setMode('fly'); syncFPCamera();
}
function syncFPCamera(){
  if (mode === 'walk'){
    const {theta, phi} = FP;
    camera.position.copy(biomePos(theta, phi, 1.7/U*100*0.017));  // 眼高 ≈1.7 m
    camera.position.copy(biomePos(theta, phi, 0.017));
    const up = biomeUp(theta, phi), fwd = biomeTangent(theta);
    const right = new THREE.Vector3().crossVectors(fwd, up).normalize();
    const m = new THREE.Matrix4().makeBasis(right, up, fwd.clone().negate());
    camera.quaternion.setFromRotationMatrix(m);
    camera.rotateY(FP.yaw); camera.rotateX(FP.pitch);
    camera.up.copy(up);
  } else if (mode === 'fly'){
    camera.position.copy(FP.pos);
    camera.up.set(0,1,0);
    camera.quaternion.setFromEuler(new THREE.Euler(FP.pitch, FP.yaw, 0, 'YXZ'));
  }
}
function updateFP(dt){
  const run = FP.keys.has('shift') ? 2.6 : 1;
  if (mode === 'walk'){
    const step = 0.028 * run * dt * 60 / 60 * 60 * dt;   // ≈ 1.6 m/s(走) / 4 m/s(跑)
    const sp = 0.016 * run * (dt*60);
    let f = 0, s = 0;
    if (FP.keys.has('w')) f += 1; if (FP.keys.has('s')) f -= 1;
    if (FP.keys.has('d')) s += 1; if (FP.keys.has('a')) s -= 1;
    if (f || s){
      const dir = new THREE.Vector3();
      camera.getWorldDirection(dir);
      const up = biomeUp(FP.theta, FP.phi);
      const flat = dir.clone().projectOnPlane(up).normalize();
      const right = new THREE.Vector3().crossVectors(up, flat).normalize().negate();
      const mv = flat.multiplyScalar(f).add(right.multiplyScalar(s)).normalize().multiplyScalar(sp);
      const tang = biomeTangent(FP.theta), lat = biomeLateral(FP.theta, FP.phi);
      const rr = C.tube - .017;
      FP.theta += mv.dot(tang) / (C.ringR + rr*Math.cos(FP.phi));
      FP.phi   += mv.dot(lat) / rr;
      const [t0,t1] = interior.userData.range;
      FP.theta = THREE.MathUtils.clamp(FP.theta, t0+.004, t1-.004);
      FP.phi   = THREE.MathUtils.clamp(FP.phi, -1.28, 1.28);
    }
    syncFPCamera();
  } else if (mode === 'fly'){
    const sp = .05 * run * (dt*60);
    const dir = new THREE.Vector3(); camera.getWorldDirection(dir);
    const right = new THREE.Vector3().crossVectors(dir, new THREE.Vector3(0,1,0)).normalize();
    const mv = new THREE.Vector3();
    if (FP.keys.has('w')) mv.add(dir); if (FP.keys.has('s')) mv.sub(dir);
    if (FP.keys.has('d')) mv.add(right); if (FP.keys.has('a')) mv.sub(right);
    if (FP.keys.has('e')) mv.y += 1;   if (FP.keys.has('q')) mv.y -= 1;
    if (mv.lengthSq()) FP.pos.add(mv.normalize().multiplyScalar(sp));
    FP.pos.z = THREE.MathUtils.clamp(FP.pos.z, -18, 18);
    const rl = Math.hypot(FP.pos.x, FP.pos.y), lim = C.spineR*.92 - .25;
    if (rl > lim){ FP.pos.x *= lim/rl; FP.pos.y *= lim/rl; }
    syncFPCamera();
  }
}

/* --- 外部相机聚焦 --- */
const FOCUS = {
  shield  : [new THREE.Vector3(0,0,-C.spineLen/2-6),  new THREE.Vector3(16,10,-C.spineLen/2-34)],
  ringA   : [new THREE.Vector3(0,0,-C.ringGap/2),     new THREE.Vector3(30,16,-C.ringGap/2-34)],
  spineMid: [new THREE.Vector3(0,0,0),                new THREE.Vector3(11,6,16)],
  ringB   : [new THREE.Vector3(0,0,C.ringGap/2),      new THREE.Vector3(-30,-16,C.ringGap/2+34)],
  drive   : [new THREE.Vector3(0,0,C.spineLen/2+16),  new THREE.Vector3(22,12,C.spineLen/2+46)],
  whole   : [new THREE.Vector3(0,0,0),                new THREE.Vector3(46,26,90)]
};
function focusOn(key){
  if (mode !== 'ext') setMode('ext');
  const [tg, cp] = FOCUS[key] || FOCUS.whole;
  tween = {t:0, dur:1.2, p0:camera.position.clone(), p1:cp.clone(),
           g0:controls.target.clone(), g1:tg.clone()};
}

/* ============================================================
   5. 交互
   ============================================================ */
const ray = new THREE.Raycaster(), ndc = new THREE.Vector2();
let showLabels = true, downXY = null;

renderer.domElement.addEventListener('pointerdown', e=>{
  downXY = [e.clientX, e.clientY];
  if (mode !== 'ext'){ FP.drag = true; FP.lx = e.clientX; FP.ly = e.clientY; }
});
addEventListener('pointerup', e=>{
  FP.drag = false;
  if (!downXY) return;
  const moved = Math.hypot(e.clientX-downXY[0], e.clientY-downXY[1]);
  downXY = null;
  if (moved > 5) return;                          // 拖动不算点击
  ndc.set((e.clientX/innerWidth)*2-1, -(e.clientY/innerHeight)*2+1);
  ray.setFromCamera(ndc, camera);
  if (mode === 'ext'){
    const hit = ray.intersectObjects(biomeMeshes, false)[0];
    if (hit) enterBiome(hit.object.userData.index);
  } else {
    const hit = ray.intersectObjects(hotMeshes, false)[0];
    if (hit) showCard(hit.object.userData.key);
  }
});
addEventListener('pointermove', e=>{
  if (!FP.drag || mode==='ext') return;
  FP.yaw   -= (e.clientX - FP.lx) * .0032;
  FP.pitch -= (e.clientY - FP.ly) * .0032;
  FP.pitch = THREE.MathUtils.clamp(FP.pitch, -1.4, 1.4);
  FP.lx = e.clientX; FP.ly = e.clientY;
  syncFPCamera();
});
addEventListener('keydown', e=>{
  const k = e.key.toLowerCase();
  FP.keys.add(k === 'shift' ? 'shift' : k);
  if (k === 'escape') setMode('ext');
  if (k === 'i' && mode === 'ext') enterBiome(curBiome);
  if (mode !== 'ext' && ['w','a','s','d','q','e'].includes(k)) e.preventDefault();
});
addEventListener('keyup', e=>FP.keys.delete(e.key.toLowerCase() === 'shift' ? 'shift' : e.key.toLowerCase()));
addEventListener('blur', ()=>FP.keys.clear());
addEventListener('resize', ()=>{
  camera.aspect = innerWidth/innerHeight; camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight); labelRenderer.setSize(innerWidth, innerHeight);
  if (composer) composer.setSize(innerWidth, innerHeight);
});
// 舱内滚轮 = 变焦（望远）
renderer.domElement.addEventListener('wheel', e=>{
  if (mode === 'ext') return;
  camera.fov = THREE.MathUtils.clamp(camera.fov + Math.sign(e.deltaY)*3, 18, 78);
  camera.updateProjectionMatrix();
}, {passive:true});

function showCard(key){
  const [t,b] = HOTSPOTS[key];
  document.getElementById('card-t').textContent = t;
  document.getElementById('card-b').textContent = b;
  document.getElementById('card').style.display = 'block';
}
function hideCard(){ document.getElementById('card').style.display = 'none'; }
document.getElementById('card-x').onclick = hideCard;

/* --- UI --- */
const sel = document.getElementById('sel-biome');
BIOMES.forEach(([n,p],i)=>{
  const o = document.createElement('option');
  o.value = i; o.textContent = `${i<12?'A':'B'}${i%12+1} · ${n} — ${PROFILE[p].name}`;
  sel.appendChild(o);
});
sel.onchange = () => enterBiome(+sel.value);
document.getElementById('b-ext').onclick = () => focusOn('whole');
document.getElementById('b-in').onclick = () => enterBiome(curBiome);
document.getElementById('b-spine').onclick = enterSpine;
document.getElementById('b-prev').onclick = () => enterBiome((curBiome+23)%24);
document.getElementById('b-next').onclick = () => enterBiome((curBiome+1)%24);
document.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>focusOn(b.dataset.focus));

let spinMul = 10, dayLen = 90;
const rs = document.getElementById('r-spin'), rd = document.getElementById('r-day');
const vs = document.getElementById('v-spin'), vd = document.getElementById('v-day');
const syncSliders = ()=>{ spinMul = +rs.value; dayLen = +rd.value;
  vs.textContent = spinMul===0 ? '停转' : '×'+spinMul; vd.textContent = dayLen+'s'; };
rs.oninput = rd.oninput = syncSliders; syncSliders();
document.getElementById('c-lbl').onchange = e=>{
  showLabels = e.target.checked;
  labelObjs.forEach(o=>o.visible = showLabels && mode==='ext');
  document.getElementById('labels').style.display = showLabels ? '' : 'none';
};
document.getElementById('c-rot').onchange = e=>controls.autoRotate = e.target.checked;
document.getElementById('c-bloom').onchange = e=>useBloom = e.target.checked && !!composer;

/* ============================================================
   6. 后处理（泛光，加载失败则降级）
   ============================================================ */
let composer = null, useBloom = true;
try{
  const [{EffectComposer},{RenderPass},{UnrealBloomPass},{OutputPass}] = await Promise.all([
    import('three/addons/postprocessing/EffectComposer.js'),
    import('three/addons/postprocessing/RenderPass.js'),
    import('three/addons/postprocessing/UnrealBloomPass.js'),
    import('three/addons/postprocessing/OutputPass.js')
  ]);
  composer = new EffectComposer(renderer);
  composer.addPass(new RenderPass(scene, camera));
  composer.addPass(new UnrealBloomPass(new THREE.Vector2(innerWidth, innerHeight), .62, .75, .82));
  composer.addPass(new OutputPass());
}catch(err){ console.warn('bloom 不可用，降级为直接渲染：', err); useBloom = false; }

/* ============================================================
   7. 主循环
   ============================================================ */
const clock = new THREE.Clock();
let elapsed = 0;
function mulberry32(a){ return function(){ a|=0; a=a+0x6D2B79F5|0;
  let t=Math.imul(a^a>>>15, 1|a); t=t+Math.imul(t^t>>>7, 61|t)^t;
  return ((t^t>>>14)>>>0)/4294967296; }; }

function animate(){
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), .05); elapsed += dt;

  // 环自转（反向，抵消角动量）
  const w = (Math.PI*2 / C.spinPeriod) * spinMul * dt;
  parts.ringA.rotation.z += w;
  parts.ringB.rotation.z -= w;

  // 推进器排焰 / 星光闪烁 / 尘埃流
  parts.plumeMat.uniforms.uT.value = elapsed;
  parts.plume.scale.set(1, .94 + Math.sin(elapsed*7.3)*.05, 1);
  parts.driveGlow.intensity = 800 + Math.sin(elapsed*9)*160;
  stars.material.uniforms.uT.value = elapsed;
  if (mode === 'ext'){
    const p = dustGeo.attributes.position.array;
    for (let i=0;i<DUST;i++){
      p[i*3+2] += 260*dt;
      if (p[i*3+2] > 260) resetDust(i);
    }
    dustGeo.attributes.position.needsUpdate = true;
    stars.rotation.y += dt*.0012;
  }

  // 舱内昼夜（sunline 调光）
  if (mode !== 'ext' && interior.userData.sun){
    dayT = (dayT + dt/dayLen) % 1;
    const day = Math.max(0, Math.sin(dayT*Math.PI*2 - Math.PI/2)*.5+.5);
    const level = 0.06 + 0.94*Math.pow(day, .7);
    const warm = 1 - Math.abs(day-.5)*1.4;                    // 晨昏偏暖
    const col = new THREE.Color().setHSL(.09 + .02*(1-warm), .35*(1-day)+.05, .5);
    interior.userData.sun.material.color.setRGB(level, level*(0.94+0.06*day), level*(0.82+0.18*day));
    interior.userData.sunGlow.material.opacity = .12 + .35*level;
    intLights.forEach(L=>{
      if (L.isPointLight) { L.intensity = 2.6*level; L.color.lerp(col, .02); }
      if (L.isAmbientLight) L.intensity = .10 + .5*level;
    });
    const sh = interior.userData.shell;
    if (sh) sh.material.emissiveIntensity = .04 + .34*level;
    const hh = Math.floor(dayT*24), mm = Math.floor(dayT*1440%60);
    document.getElementById('h-spin').textContent =
      `舱内时间 ${String(hh).padStart(2,'0')}:${String(mm).padStart(2,'0')} · 1 g`;
  } else {
    document.getElementById('h-spin').textContent = '90 s / 圈 ≈ 1 g';
  }

  // HUD：航程读数（1 现实秒 = 0.05 船年，仅示意）
  const y = elapsed*0.05;
  const shipYear = C.launchYear + (y % C.voyage);
  document.getElementById('h-year').textContent =
    `${shipYear.toFixed(1)} 年（第 ${(y%C.voyage).toFixed(1)} / ${C.voyage} 年）`;
  document.getElementById('h-dist').textContent = `${(0.1*(y%C.voyage)).toFixed(2)} 光年`;

  // 相机补间
  if (tween){
    tween.t += dt/tween.dur;
    const k = Math.min(1, tween.t), e = k<.5 ? 2*k*k : 1-Math.pow(-2*k+2,2)/2;
    camera.position.lerpVectors(tween.p0, tween.p1, e);
    controls.target.lerpVectors(tween.g0, tween.g1, e);
    if (k >= 1) tween = null;
  }

  if (mode === 'ext'){ camera.up.set(0,1,0); controls.update(); }
  else updateFP(dt);

  if (composer && useBloom) composer.render(); else renderer.render(scene, camera);
  labelRenderer.render(scene, camera);
}

/* ============================================================
   8. 启动 + 自检（?test=1）
   ============================================================ */
setMode('ext'); focusOn('whole'); animate();
document.getElementById('boot').style.display = 'none';

if (new URLSearchParams(location.search).has('test')){
  const out = [], ok = (n,c)=>out.push(`<div class="${c?'p':'f'}">${c?'PASS':'FAIL'} · ${n}</div>`);
  ok('WebGL 上下文', !!renderer.getContext());
  ok('24 个生物群区舱段', biomeMeshes.length === 24);
  ok('每环 12 舱', biomeMeshes.filter(m=>m.userData.index<12).length === 12);
  ok('双环存在且分居脊柱两侧',
     parts.ringA.position.z < 0 && parts.ringB.position.z > 0);
  ok('全船长度 ≈ 9.6 km', Math.abs(C.spineLen*U/1000 - 9.6) < .01);
  ok('环周长 ≈ 12.57 km', Math.abs(2*Math.PI*C.ringR*U/1000 - 12.566) < .01);
  ok('单舱长度 ≈ 1.05 km', Math.abs(C.ringR*ARC*U/1000 - 1.047) < .01);
  ok('90 s 自转在 floor 处 ≈1 g',
     Math.abs(Math.pow(2*Math.PI/C.spinPeriod,2)*(C.ringR*U)/9.81 - 1) < 0.05);
  const l0 = labelObjs.length; ok('部件标注 ≥ 9', l0 >= 9);
  // 进入内部 → 检查 sunline / 热点 / 相机在舱内
  enterBiome(0);
  ok('进入舱内模式', mode === 'walk');
  ok('sunline 已生成', !!interior.userData.sun);
  ok('舱内热点 ≥ 6', hotMeshes.length >= 6);
  const r = camera.position.length();
  ok('相机位于舱内地面附近', Math.abs(r - (C.ringR + C.tube - .017)) < .2);
  const before = FP.theta; FP.keys.add('w'); updateFP(.5); FP.keys.delete('w');
  ok('步行移动改变位置', Math.abs(FP.theta - before) > 1e-6);
  enterSpine(); ok('进入脊柱零重力模式', mode === 'fly');
  setMode('ext'); focusOn('whole'); ok('返回外部视图', mode === 'ext' && ship.visible);
  const t = document.getElementById('test');
  t.style.display = 'block';
  t.innerHTML = `<b>SELF-TEST</b> ${out.join('')}<div style="color:#8fa3ba">${
    out.filter(s=>s.includes('PASS')).length}/${out.length} passed · bloom=${!!composer}</div>`;
  console.table(out.map(s=>s.replace(/<[^>]+>/g,'')));
}
