  gdp:     { name:'GDP',    unitCity:'亿美元', unitReg:'万亿美元', cityF:v=>v.toFixed(0), regF:v=>v.toFixed(2) },
  pop:     { name:'人口',   unitCity:'百万人', unitReg:'百万人',   cityF:v=>v.toFixed(1), regF:v=>v.toFixed(0) },
  flights: { name:'航班量', unitCity:'百万客/年', unitReg:'百万客/年', cityF:v=>v.toFixed(1), regF:v=>v.toFixed(0) }
};
