/** 经纬度 -> 三维坐标（与等距圆柱投影贴图对齐） */
function ll2v(lat, lon, r = R, out = new THREE.Vector3()){
  const phi = (90 - lat) * Math.PI / 180;
  const th  = (lon + 180) * Math.PI / 180;
  return out.set(-r*Math.sin(phi)*Math.cos(th), r*Math.cos(phi), r*Math.sin(phi)*Math.sin(th));
}
const clamp = (v,a,b)=>Math.min(b,Math.max(a,v));
const lerp  = (a,b,t)=>a+(b-a)*t;
function hash(s){ let h=2166136261; for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);} return ((h>>>0)%10000)/10000; }
/** 大圆距离 km */
function gcKm(a,b){
  const t=Math.PI/180, la1=a.lat*t, la2=b.lat*t, dl=(b.lon-a.lon)*t;
  const c=Math.sin(la1)*Math.sin(la2)+Math.cos(la1)*Math.cos(la2)*Math.cos(dl);
  return 6371*Math.acos(clamp(c,-1,1));
}
/** 颜色标尺 (低->高)：深蓝 → 青 → 绿 → 黄 → 橙红 */
const RAMP = [[12,32,86],[16,110,178],[26,196,190],[126,214,102],[248,214,86],[246,138,48],[224,58,52]];
function ramp(t){
  t = clamp(t,0,1)*(RAMP.length-1);
  const i = Math.min(RAMP.length-2, Math.floor(t)), f = t-i;
  const a = RAMP[i], b = RAMP[i+1];
  return [Math.round(lerp(a[0],b[0],f)), Math.round(lerp(a[1],b[1],f)), Math.round(lerp(a[2],b[2],f))];
}
const rampCss = t => { const c = ramp(t); return `rgb(${c[0]},${c[1]},${c[2]})`; };

/** 随年份增长的指标值（含 2020-2021 航空业下滑） */
function valueAt(base, g, year, key, m){
  const t = year - Y0;
  let v = base * Math.pow(1+g, t);
  v *= 1 + 0.025*Math.sin(hash(key+m)*12 + t*1.6);
  if (m === 'flights'){
