function loadTex(url){
  return new Promise(res=>{
    new THREE.TextureLoader().setCrossOrigin('anonymous').load(url,
      t=>{ t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = renderer.capabilities.getMaxAnisotropy(); res(t); },
      undefined, ()=>res(null));
  });
}
function projX(lon,W){ return (lon+180)/360*W; }
function projY(lat,H){ return (90-lat)/180*H; }
function fillPoly(ctx, poly, W, H){
  ctx.beginPath();
  poly.forEach((p,i)=>{ const x=projX(p[0],W), y=projY(p[1],H); i?ctx.lineTo(x,y):ctx.moveTo(x,y); });
  ctx.closePath(); ctx.fill();
}
