/* ============================================================
   4. 地球（自定义着色器：昼夜分界 + 城市灯光 + 海面高光）
   ============================================================ */
const earthUni = {
  uDay:{value:null}, uNight:{value:null},
  uSun:{value:new THREE.Vector3(1,0,0)},   // 地球本地坐标系
  uCam:{value:new THREE.Vector3()},        // 地球本地坐标系
  uNight_gain:{value:1.3}, uTime:{value:0}
};
const earthMat = new THREE.ShaderMaterial({
  uniforms: earthUni,
  vertexShader:/*glsl*/`
    varying vec2 vUv; varying vec3 vPos; varying vec3 vNrm;
    void main(){
      vUv = uv; vPos = position; vNrm = normalize(normal);
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0);
    }`,
  fragmentShader:/*glsl*/`
    uniform sampler2D uDay; uniform sampler2D uNight;
    uniform vec3 uSun; uniform vec3 uCam;
    uniform float uNight_gain; uniform float uTime;
    varying vec2 vUv; varying vec3 vPos; varying vec3 vNrm;
    void main(){
      vec3 N = normalize(vNrm);
      vec3 V = normalize(uCam - vPos);
      vec3 S = normalize(uSun);
      float s = dot(N, S);
      float day = smoothstep(-0.14, 0.22, s);          // 昼夜分界线（带晨昏蒙影）

      vec3 dayC   = texture2D(uDay, vUv).rgb;
      vec3 nightC = texture2D(uNight, vUv).rgb;
      float water = clamp((dayC.b - dayC.r*0.85) * 4.0, 0.0, 1.0);

      vec3 col = dayC * (0.14 + 1.12 * clamp(s, 0.0, 1.0));
      // 海面镜面高光
      vec3 H = normalize(S + V);
      col += vec3(0.9,0.95,1.0) * pow(max(dot(N,H),0.0), 42.0) * water * smoothstep(0.0,0.18,s) * 0.6;
      // 夜面城市灯光（含轻微闪烁）
      float tw = 0.9 + 0.1*sin(uTime*2.2 + vUv.x*420.0 + vUv.y*260.0);
      vec3 lights = nightC * vec3(1.15,0.92,0.60) * uNight_gain * tw;
      col = mix(col*0.05 + lights, col, day);
      // 晨昏线附近的暖色散射
      float term = exp(-pow(s*7.0, 2.0));
      col += vec3(0.55,0.30,0.12) * term * 0.22;
      // 边缘大气
      float rim = pow(1.0 - max(dot(N,V),0.0), 3.0);
      col += vec3(0.25,0.45,0.9) * rim * (0.22 + 0.78*day);

      gl_FragColor = vec4(col, 1.0);
      #include <colorspace_fragment>
    }`
});
const earth = new THREE.Mesh(new THREE.SphereGeometry(R, 128, 96), earthMat);
earthGroup.add(earth);

