  const vals = REGIONS.map(r=>regValue(r,year));
  const mn = Math.min(...vals), mx = Math.max(...vals);
  heatRange = [mn,mx];
  const lmn=Math.log(mn), lmx=Math.log(mx);
  REGIONS.forEach((r,i)=>{
    const t = (Math.log(vals[i]) - lmn) / Math.max(1e-6, lmx-lmn);
    const c = ramp(t);
    heatCtx.fillStyle = `rgba(${c[0]},${c[1]},${c[2]},0.9)`;
    fillPoly(heatCtx, r.poly, W, H);
    heatCtx.strokeStyle = 'rgba(255,255,255,0.16)'; heatCtx.lineWidth = 1.2;
    heatCtx.beginPath();
    r.poly.forEach((p,k)=>{ const x=projX(p[0],W), y=projY(p[1],H); k?heatCtx.lineTo(x,y):heatCtx.moveTo(x,y); });
    heatCtx.closePath(); heatCtx.stroke();
  });
  heatTex.needsUpdate = true;
  updateLegend();
}

