/* ============================================================
   7. 航线弧（大圆插值 + 流动脉冲着色器）
   ============================================================ */
function arcCurve(a, b, seg=110){
  const va = ll2v(a.lat,a.lon,1), vb = ll2v(b.lat,b.lon,1);
  const ang = va.angleTo(vb), sa = Math.sin(ang);
  const h = 0.10 + 0.30*(ang/Math.PI);
  const pts = [];
  for(let i=0;i<=seg;i++){
    const t=i/seg;
    const p = new THREE.Vector3();
    if (sa < 1e-6) p.copy(va).lerp(vb,t).normalize();
    else p.copy(va).multiplyScalar(Math.sin((1-t)*ang)/sa)
          .addScaledVector(vb, Math.sin(t*ang)/sa).normalize();
    p.multiplyScalar(R*(1 + h*Math.sin(Math.PI*t)));
    pts.push(p);
  }
  return new THREE.CatmullRomCurve3(pts);
}
const arcVS = /*glsl*/`
  varying vec2 vUv;
  void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`;
const arcFS = /*glsl*/`
  uniform vec3 uColor; uniform float uTime, uSpeed, uPhase, uOpacity, uBase;
  varying vec2 vUv;
  void main(){
    float head = fract(uTime * uSpeed + uPhase);
    float d = vUv.x - head; d -= floor(d);            // 与光头的距离(尾随)
    float pulse = exp(-d * 15.0) + 0.55*exp(-d*60.0);
    float ends = smoothstep(0.0,0.05,vUv.x) * smoothstep(1.0,0.95,vUv.x);
    float a = (uBase + pulse) * uOpacity * ends;
    vec3 col = mix(uColor, vec3(1.0,0.98,0.92), clamp(pulse,0.0,1.0)*0.75);
    gl_FragColor = vec4(col, clamp(a,0.0,1.0));
    #include <colorspace_fragment>
  }`;
const arcGroup = new THREE.Group(); earthGroup.add(arcGroup);
ROUTES.forEach(r=>{
  const curve = arcCurve(r.a, r.b);
  const geo = new THREE.TubeGeometry(curve, 128, 0.0035, 5, false);
  const mat = new THREE.ShaderMaterial({
    uniforms:{
      uColor:{value:new THREE.Color().setHSL(0.52 - 0.18*hash(r.flight), 0.9, 0.62)},
      uTime:{value:0}, uSpeed:{value:0.12 + 0.16*hash(r.flight+'s')},
      uPhase:{value:hash(r.flight+'p')}, uOpacity:{value:0.9}, uBase:{value:0.16}
    },
    vertexShader:arcVS, fragmentShader:arcFS,
    transparent:true, blending:THREE.AdditiveBlending, depthWrite:false
  });
  const m = new THREE.Mesh(geo, mat);
  m.userData = { route:r }; r.mesh = m; arcGroup.add(m);
});

/* ============================================================
   8. 时间 / 太阳位置（昼夜分界物理一致）
   ============================================================ */
const state = { year:Y0, hour:12, doy:172, playing:false, speed:1, spin:1 };
function sunLocal(){
  const dec = -23.44 * Math.cos(2*Math.PI*(state.doy+10)/365.24);   // 太阳赤纬
  const lon = -15 * (state.hour - 12);                             // 直射点经度
  return { dec, lon, v: ll2v(dec, lon, 1) };
}
function applyTime(){
  const s = sunLocal();
  earthUni.uSun.value.copy(s.v);
  // 地球自转角 = -直射点经度 → 太阳在世界坐标中固定于 +X
  earthGroup.rotation.y = THREE.MathUtils.degToRad(-s.lon);
  atmUni.uSunW.value.copy(s.v).applyAxisAngle(new THREE.Vector3(0,1,0), earthGroup.rotation.y);
  document.getElementById('hClock').textContent =
    String(Math.floor(state.hour)%24).padStart(2,'0')+':'+String(Math.floor(state.hour%1*60)).padStart(2,'0');
  document.getElementById('hDoy').textContent = state.doy;
}

/* ============================================================
   9. 数据驱动更新（城市点尺寸、航线粗细、热力层、排行）
   ============================================================ */
let lastHeatYear = -1;
function updateData(force=false){
  const y = state.year;
  document.getElementById('yearLabel').textContent = Math.round(y);
  document.getElementById('hYear').textContent = Math.round(y);

  // 城市点：按指标归一化尺寸
  const cv = CITIES.map(c=>cityValue(c,y));
  const lmn = Math.log(Math.min(...cv)), lmx = Math.log(Math.max(...cv));
  CITIES.forEach((c,i)=>{
    const t = (Math.log(cv[i]) - lmn) / Math.max(1e-6, lmx-lmn);
    c.norm = t; c.cur = cv[i];
    const s = 0.028 + 0.085*Math.pow(t,0.85);
    c.sprite.scale.set(s,s,1);
    const col = ramp(t);
    c.sprite.material.color.setRGB(col[0]/255*1.1, col[1]/255*1.1, col[2]/255*1.1);
    c.core.scale.setScalar(0.7 + t*1.6);
  });

  // 航线：客流决定亮度
  const rv = ROUTES.map(r=>routePax(r,y));
  const rmx = Math.max(...rv);
  ROUTES.forEach((r,i)=>{
    r.cur = rv[i];
    const t = rv[i]/rmx;
    r.mesh.material.uniforms.uOpacity.value = 0.35 + 0.65*Math.pow(t,0.6);
    r.mesh.material.uniforms.uBase.value = 0.10 + 0.14*t;
  });

  // 热力层（播放时节流重绘）
  if (force || Math.abs(y-lastHeatYear) > 0.12){ drawHeat(y); lastHeatYear = y; }
  updateRank();
  if (activeCity) fillCard(activeCity);
}
function fmtReg(v){ return METRICS[metric].regF(v) + ' ' + METRICS[metric].unitReg; }
function updateRank(){
  const y = state.year;
  const arr = REGIONS.map(r=>({ name:r.name, v:regValue(r,y) })).sort((a,b)=>b.v-a.v).slice(0,6);
  const mx = arr[0].v;
  document.getElementById('rankTitle').textContent = `地区排行 · ${METRICS[metric].name}`;
  document.getElementById('rank').innerHTML = arr.map((d,i)=>
    `<div class="r" style="background:linear-gradient(90deg,${rampCss(d.v/mx)}33 ${d.v/mx*100}%,rgba(255,255,255,.03) 0)">
       <span>${i+1}. ${d.name}</span><i>${fmtReg(d.v)}</i></div>`).join('');
}
function updateLegend(){
  const stops = [0,.16,.33,.5,.66,.83,1].map(t=>`${rampCss(t)} ${t*100}%`).join(',');
  document.getElementById('bar').style.background = `linear-gradient(90deg,${stops})`;
  document.getElementById('legendTitle').textContent = `${METRICS[metric].name} 热力标尺（${METRICS[metric].unitReg}）`;
  document.getElementById('lgMin').textContent = METRICS[metric].regF(heatRange[0]);
  document.getElementById('lgMax').textContent = METRICS[metric].regF(heatRange[1]);
}

/* ============================================================
   10. 交互：拾取、弹窗、提示
   ============================================================ */
const ray = new THREE.Raycaster();
const ndc = new THREE.Vector2();
const tip = document.getElementById('tip');
const card = document.getElementById('card');
let activeCity = null, hoverArc = null, pointerDown=null, moved=false;

function setNdc(e){ ndc.x = (e.clientX/innerWidth)*2-1; ndc.y = -(e.clientY/innerHeight)*2+1; }
function pick(){
  ray.setFromCamera(ndc, camera);
  if (cityGroup.visible){
    const hs = ray.intersectObjects(cityGroup.children, false).filter(h=>h.object.userData.city);
    if (hs.length) return { type:'city', city:hs[0].object.userData.city };
  }
  if (arcGroup.visible){
    const hs = ray.intersectObjects(arcGroup.children, false);
    if (hs.length) return { type:'arc', route:hs[0].object.userData.route };
  }
  return null;
}
function showTip(html, x, y){
  tip.innerHTML = html; tip.style.opacity = 1;
  const r = tip.getBoundingClientRect();
  tip.style.left = Math.min(innerWidth - r.width - 10, x + 14) + 'px';
  tip.style.top  = Math.min(innerHeight - r.height - 10, y + 14) + 'px';
}
const hideTip = ()=>{ tip.style.opacity = 0; };

renderer.domElement.addEventListener('pointerdown', e=>{ pointerDown={x:e.clientX,y:e.clientY}; moved=false; });
renderer.domElement.addEventListener('pointermove', e=>{
  if (pointerDown && (Math.abs(e.clientX-pointerDown.x)>4 || Math.abs(e.clientY-pointerDown.y)>4)) moved=true;
  setNdc(e);
  const h = pick();
  // 复位上一条高亮航线
  if (hoverArc && (!h || h.type!=='arc' || h.route!==hoverArc)){ hoverArc.mesh.material.uniforms.uBase.value *= 0.5; hoverArc = null; }
  if (!h){ hideTip(); renderer.domElement.style.cursor='grab'; return; }
  renderer.domElement.style.cursor='pointer';
  if (h.type === 'city'){
    const c = h.city, M = METRICS[metric];
    showTip(`<div class="h">${c.name} <span style="color:#8ea6c8">${c.code}</span></div>
      <div class="l"><span>${M.name}</span><span>${M.cityF(c.cur)} ${M.unitCity}</span></div>
      <div class="l"><span>直飞航线</span><span>${c.routes.length} 条</span></div>
      <div class="l" style="color:#4fd1ff"><span>点击查看详情</span><span></span></div>`, e.clientX, e.clientY);
  } else {
    const r = h.route;
    if (hoverArc !== r){ hoverArc = r; r.mesh.material.uniforms.uBase.value *= 2; }
    const hrs = r.km/850 + 0.6;
    showTip(`<div class="h">${r.airline} ${r.flight}</div>
      <div class="l"><span>航段</span><span>${r.a.name} → ${r.b.name}</span></div>
      <div class="l"><span>机型</span><span>${r.ac}</span></div>
      <div class="l"><span>大圆距离</span><span>${r.km.toLocaleString()} km</span></div>
      <div class="l"><span>预计飞行</span><span>${Math.floor(hrs)}h ${Math.round(hrs%1*60)}m</span></div>
      <div class="l"><span>年客运量</span><span>${r.cur.toFixed(2)} 百万人</span></div>
      <div class="l"><span>周班次(估)</span><span>${Math.max(1,Math.round(r.cur*1e6/52/260))} 班</span></div>`,
      e.clientX, e.clientY);
  }
});
renderer.domElement.addEventListener('pointerup', e=>{
  pointerDown = null;
  if (moved) return;                       // 拖拽旋转不触发点击
  setNdc(e);
  const h = pick();
  if (h && h.type==='city') openCard(h.city);
  else if (!h) closeCard();
});
renderer.domElement.addEventListener('pointerleave', hideTip);

function openCard(c){ activeCity = c; fillCard(c); card.classList.add('on'); }
function closeCard(){ activeCity = null; card.classList.remove('on'); }
document.getElementById('cardX').onclick = closeCard;
function fillCard(c){
  const y = state.year;
  document.getElementById('cName').textContent = `${c.name} (${c.code})`;
  document.getElementById('cSub').textContent =
    `${c.country} · ${c.lat.toFixed(2)}°, ${c.lon.toFixed(2)}° · ${Math.round(y)} 年`;
  const rows = [
    ['GDP', METRICS.gdp.cityF(cityValue(c,y,'gdp')) + ' 亿美元'],
    ['人口', METRICS.pop.cityF(cityValue(c,y,'pop')) + ' 百万人'],
    ['航空客运', METRICS.flights.cityF(cityValue(c,y,'flights')) + ' 百万客/年'],
    ['人均 GDP', (cityValue(c,y,'gdp')*1e8/(cityValue(c,y,'pop')*1e6)/1e3).toFixed(1) + ' 千美元']
  ];
  document.getElementById('cKV').innerHTML =
    rows.map(r=>`<div class="kv"><span>${r[0]}</span><span>${r[1]}</span></div>`).join('');
  const top = c.routes.map(r=>({ r, v:routePax(r,y) })).sort((a,b)=>b.v-a.v).slice(0,4);
  document.getElementById('cRt').innerHTML = `直飞航线 ${c.routes.length} 条，主要航段：<br>` +
    (top.length ? top.map(t=>{
      const o = t.r.a===c ? t.r.b : t.r.a;
      return `· <b>${o.name}</b> ${t.r.flight} · ${t.v.toFixed(2)} 百万客`;
    }).join('<br>') : '（暂无数据）');
}

/* ============================================================
   11. UI 绑定
   ============================================================ */
const $ = id=>document.getElementById(id);
$('metricSeg').addEventListener('click', e=>{
  const b = e.target.closest('button'); if(!b) return;
  [...$('metricSeg').children].forEach(x=>x.classList.toggle('on', x===b));
