$('doy').addEventListener('input',  e=>{ state.doy = +e.target.value;  $('doyLabel').textContent = state.doy; applyTime(); });
$('opa').addEventListener('input',  e=>{ heatMesh.material.opacity = +e.target.value; $('opaLabel').textContent = (+e.target.value).toFixed(2); });
$('nl').addEventListener('input',   e=>{ earthUni.uNight_gain.value = +e.target.value; $('nlLabel').textContent = (+e.target.value).toFixed(2); });
$('tHeat').onchange  = e=>heatMesh.visible   = e.target.checked;
$('tArc').onchange   = e=>arcGroup.visible   = e.target.checked;
