/* ============================================================
   12. 主循环
   ============================================================ */
const clock = new THREE.Clock();
const camLocal = new THREE.Vector3();
let fpsT = 0, fpsN = 0;

function tick(){
  const dt = Math.min(0.05, clock.getDelta());
  const t  = clock.elapsedTime;

  // 时间推进：自转 = 模拟时钟推进（昼夜线保持在空间中固定）
  if (state.spin > 0){
    state.hour += dt * state.spin * 1.2;
    while (state.hour >= 24){ state.hour -= 24; state.doy = state.doy % 365 + 1; $('doy').value = state.doy; $('doyLabel').textContent = state.doy; }
    $('hour').value = state.hour; $('hourLabel').textContent = state.hour.toFixed(1);
    applyTime();
  }
  // 时间轴播放
  if (state.playing){
    state.year += dt * 1.15 * state.speed;
    if (state.year > Y1) state.year = Y0;
    $('year').value = state.year;
    updateData();
  }

  // 着色器 uniform 更新
  earthUni.uTime.value = t;
  earth.worldToLocal(camLocal.copy(camera.position));
  earthUni.uCam.value.copy(camLocal);
  arcGroup.children.forEach(m=>{ m.material.uniforms.uTime.value = t; });

  // 标签：背面隐藏 + 距离自适应大小
  if (labelGroup.visible){
    const camDir = camera.position.clone().normalize();
    const d = camera.position.length();
    const scale = clamp(0.045 * d/2.5, 0.028, 0.075);
    labelGroup.children.forEach(lb=>{
      const c = lb.userData.city;
      const n = lb.position.clone().applyMatrix4(earthGroup.matrixWorld).normalize();
      const facing = n.dot(camDir) > 0.28;
      const big = c.norm > (d > 4 ? 0.65 : d > 2.4 ? 0.42 : 0);
      lb.visible = facing && big;
      lb.scale.set(scale*lb.userData.aspect, scale, 1);
    });
  }
  // 选中城市脉冲
  if (activeCity){
    const s = activeCity.sprite.scale.x;
    activeCity.core.scale.setScalar((1.2 + 0.6*Math.sin(t*5)) * (0.7 + activeCity.norm*1.6));
  }

  controls.update();
  renderer.render(scene, camera);

  fpsN++; if (t - fpsT > 0.5){ $('hFps').textContent = Math.round(fpsN/(t-fpsT)) + ' FPS'; fpsT = t; fpsN = 0; }
  requestAnimationFrame(tick);
}

